(908377, 104564, 6349, '<td valign="top">This is a beautiful abstract composed of the elements of light, sky, water, fog.  My second favorite image in the challenge.  Good luck.  10</td>', 'This is a beautiful abstract composed of the elements of light, sky, water, fog.  My second favorite image in the challenge.  Good luck.  10', '2004-09-13 21:35:19.000000', NULL, 1),
(908399, 104695, 8624, '<td valign="top">good color, but I wish we could see his face or the brand on the other side of the cow.</td>', 'good color, but I wish we could see his face or the brand on the other side of the cow.', '2004-09-13 21:51:34.000000', NULL, 1),
(908401, 104324, 8624, '<td valign="top">I''m really intrigued by this image and look forward to finding out how you did it. Is that a saliva bubble or bubble gum or glass bulb in the mouth? don''t know, but I like the result. I like the sparkly lipstick. One one complaint is the cropping - I don''t like how the edge of the mouth is cut off at the side of the frame. well done.</td>', 'I''m really intrigued by this image and look forward to finding out how you did it. Is that a saliva bubble or bubble gum or glass bulb in the mouth? don''t know, but I like the result. I like the sparkly lipstick. One one complaint is the cropping - I don''t like how the edge of the mouth is cut off at the side of the frame. well done.', '2004-09-13 21:53:28.000000', NULL, 1),
(908406, 105034, 8624, '<td valign="top">I like grainy shots like this - very evocative. your lighting could be improved though - her face is too dark for my tastes.</td>', 'I like grainy shots like this - very evocative. your lighting could be improved though - her face is too dark for my tastes.', '2004-09-13 21:54:41.000000', NULL, 1),
(908407, 104430, 8624, '<td valign="top">very nice and crisp image. I like the smoke trail and the angle of the incense stick.</td>', 'very nice and crisp image. I like the smoke trail and the angle of the incense stick.', '2004-09-13 21:55:22.000000', NULL, 1),
(908409, 103930, 8624, '<td valign="top">very impressive shot of an unfortunate event. I like the thick billowing smoke. I wish the wreck and the man in the foreground were framed better, though. they provide good photo elements to help tell the story but they are cut off.</td>', 'very impressive shot of an unfortunate event. I like the thick billowing smoke. I wish the wreck and the man in the foreground were framed better, though. they provide good photo elements to help tell the story but they are cut off.', '2004-09-13 21:59:03.000000', NULL, 1),
(908419, 105072, 8624, '<td valign="top">veri interesting composition and tack sharp. great colors in the smoke. I''ll be interested in seeing how this was created since it looks to me like the smoke is not coming from the matches.</td>', 'veri interesting composition and tack sharp. great colors in the smoke. I''ll be interested in seeing how this was created since it looks to me like the smoke is not coming from the matches.', '2004-09-13 22:11:21.000000', NULL, 1);
