(915305, 103484, 22975, '<td valign="top">wha... how.... oh, hell, can''t wait to read about it!!  this is puzzling and great for the challenge.  :)</td>', 'wha... how.... oh, hell, can''t wait to read about it!!  this is puzzling and great for the challenge.  :)', '2004-09-18 00:11:09.000000', NULL, 1),
(915306, 104908, 22975, '<td valign="top">another one i can''t wait to read about.  :)  sooooo cool.  excellent.  the best i''ve seen so far!</td>', 'another one i can''t wait to read about.  :)  sooooo cool.  excellent.  the best i''ve seen so far!', '2004-09-18 00:14:41.000000', NULL, 1),
(915311, 104914, 22975, '<td valign="top">cool colors!</td>', 'cool colors!', '2004-09-18 00:19:55.000000', NULL, 1),
(915316, 104647, 22975, '<td valign="top">you people and your "woodies" crack me up!  i keep thinking "yeah, those are tired," and then you do something else unexpected with them... thanks for the hearty giggle.</td>', 'you people and your "woodies" crack me up!  i keep thinking "yeah, those are tired," and then you do something else unexpected with them... thanks for the hearty giggle.', '2004-09-18 00:22:33.000000', NULL, 1),
(915317, 104799, 22975, '<td valign="top">how burnt toast can look beautiful is beyond me, but you did it!  i love this shot!</td>', 'how burnt toast can look beautiful is beyond me, but you did it!  i love this shot!', '2004-09-18 00:23:30.000000', NULL, 1),
(915326, 104324, 22975, '<td valign="top">um... very original... can''t say i ever would have thought of that.  :)  points for creativity.</td>', 'um... very original... can''t say i ever would have thought of that.  :)  points for creativity.', '2004-09-18 00:26:20.000000', NULL, 1),
(915376, 105067, 4226, '<td valign="top">returning for comments. Like the lighting very much. The only thing that I think might have made it look better is to let the smoke travel a little diagonally in this case.  You still get a 10</td>', 'returning for comments. Like the lighting very much. The only thing that I think might have made it look better is to let the smoke travel a little diagonally in this case.  You still get a 10', '2004-09-18 01:06:43.000000', NULL, 1),
(915377, 105072, 4226, '<td valign="top">returning for comments .Getting the three lights must have been tough.. very creative and very well executed. this is another 10 from me.</td>', 'returning for comments .Getting the three lights must have been tough.. very creative and very well executed. this is another 10 from me.', '2004-09-18 01:07:45.000000', NULL, 1),
(915381, 104853, 4226, '<td valign="top">returning for comments. The only suggestion is that keep the background paper away from the subject, so that it doesn''t lighten up and it looks black. the lighting should be from sides and not from front. Also you might like to crop the candle stand and just keep the candle top in the picture.</td>', 'returning for comments. The only suggestion is that keep the background paper away from the subject, so that it doesn''t lighten up and it looks black. the lighting should be from sides and not from front. Also you might like to crop the candle stand and just keep the candle top in the picture.', '2004-09-18 01:09:10.000000', NULL, 1),
(915385, 104876, 4226, '<td valign="top">This looks a little tilted towards right.. well let me look again.. yes it does tilt.. you might like to straighten it.. I love the clouds though</td>', 'This looks a little tilted towards right.. well let me look again.. yes it does tilt.. you might like to straighten it.. I love the clouds though', '2004-09-18 01:11:32.000000', NULL, 1),
(915387, 104600, 4226, '<td valign="top">hazy... you might like to try USM for this image...and some curves</td>', 'hazy... you might like to try USM for this image...and some curves', '2004-09-18 01:12:11.000000', NULL, 1),
(915389, 104497, 4226, '<td valign="top">Pretty neat effect on the smoke here..a little light from front to show the cigar might have helped IMO</td>', 'Pretty neat effect on the smoke here..a little light from front to show the cigar might have helped IMO', '2004-09-18 01:12:53.000000', NULL, 1),
(915390, 104396, 4226, '<td valign="top">Very nice composition</td>', 'Very nice composition', '2004-09-18 01:14:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(915410, 105053, 9581, '<td valign="top">You did a marvelous one of the best shots! If I am right is this a model? It is very questionable?  I like it! 10 maybe I like trains to much!</td>', 'You did a marvelous one of the best shots! If I am right is this a model? It is very questionable?  I like it! 10 maybe I like trains to much!', '2004-09-18 01:37:05.000000', NULL, 1),
(915418, 104346, 9581, '<td valign="top">Like the song "SMoke on the water and fire in the sky" this is it for real! nice job!</td>', 'Like the song "SMoke on the water and fire in the sky" this is it for real! nice job!', '2004-09-18 01:41:18.000000', NULL, 1),
(915424, 104647, 9581, '<td valign="top">hahahaha too funny!</td>', 'hahahaha too funny!', '2004-09-18 01:43:33.000000', NULL, 1),
(915554, 104695, 23394, '<td valign="top">this is one of my top picks in the challenge.  incredible shot--great dob, focus, composition, colors, and definitely meets the challenge.  the only thing i could offer for improvement would have been to have backed off a step and pulled around slightly to your righ so that you wouldn''t have cropped off any of the cowboy (then, again, with a moment like this, you might not always have the opportunity). way to be there!  hope this does well.</td>', 'this is one of my top picks in the challenge.  incredible shot--great dob, focus, composition, colors, and definitely meets the challenge.  the only thing i could offer for improvement would have been to have backed off a step and pulled around slightly to your righ so that you wouldn''t have cropped off any of the cowboy (then, again, with a moment like this, you might not always have the opportunity). way to be there!  hope this does well.', '2004-09-18 05:43:50.000000', NULL, 1),
(915555, 104016, 23394, '<td valign="top">this is one of my top picks for the challenge.  it is one of those shots that really brings home the reality of the world we live in--the by-product of human progress back-dropped by God''s promise.  incredible, extremely powerful composition.  (i''m not taking points away for the border, but i think the white really doesn''t do anything for the image, and would suggest that if you make it available for dpcprints, you either remove it or provide a borderless alternate.)</td>', 'this is one of my top picks for the challenge.  it is one of those shots that really brings home the reality of the world we live in--the by-product of human progress back-dropped by God''s promise.  incredible, extremely powerful composition.  (i''m not taking points away for the border, but i think the white really doesn''t do anything for the image, and would suggest that if you make it available for dpcprints, you either remove it or provide a borderless alternate.)', '2004-09-18 05:50:30.000000', NULL, 1),
(915556, 104776, 23394, '<td valign="top">beautiful shot.  love the colors.</td>', 'beautiful shot.  love the colors.', '2004-09-18 05:53:31.000000', NULL, 1),
(915557, 105067, 23394, '<td valign="top">great use of negative space.  interesting coloring.  hope this does well.</td>', 'great use of negative space.  interesting coloring.  hope this does well.', '2004-09-18 05:54:25.000000', NULL, 1),
(915558, 104908, 23394, '<td valign="top">great shot.  this typifies the reason i joined dpc--to find examples of images i want to learn how to make.  thanks for a great entry!  hope this does well.</td>', 'great shot.  this typifies the reason i joined dpc--to find examples of images i want to learn how to make.  thanks for a great entry!  hope this does well.', '2004-09-18 05:56:09.000000', NULL, 1),
(915560, 104355, 23394, '<td valign="top">first, let me say i like the idea and the basic composition.  unfortunately, the lighting is a little too strong.  it gives the fingernails an almost "E.T."-ish look.  i think if you re-shot this with half the light on the hand (and maybe with a different hand model), you''d have a killer shot.</td>', 'first, let me say i like the idea and the basic composition.  unfortunately, the lighting is a little too strong.  it gives the fingernails an almost "E.T."-ish look.  i think if you re-shot this with half the light on the hand (and maybe with a different hand model), you''d have a killer shot.', '2004-09-18 06:00:16.000000', NULL, 1),
(915561, 104941, 23394, '<td valign="top">i''ll give you this:  that is a lot of smoke.  the flash, though, really takes away from the composition.  other than the smoke, i''m not really sure what i''m looking at.</td>', 'i''ll give you this:  that is a lot of smoke.  the flash, though, really takes away from the composition.  other than the smoke, i''m not really sure what i''m looking at.', '2004-09-18 06:02:44.000000', NULL, 1),
(915562, 105051, 23394, '<td valign="top">i can see something smokey, or i could say i see smoke.  wish the focus was sharper, because the composition is excellent.</td>', 'i can see something smokey, or i could say i see smoke.  wish the focus was sharper, because the composition is excellent.', '2004-09-18 06:04:30.000000', NULL, 1),
(915563, 104799, 23394, '<td valign="top">and this is the reason i don''t cook toast...great take on the challenge, hope this does well.</td>', 'and this is the reason i don''t cook toast...great take on the challenge, hope this does well.', '2004-09-18 06:06:37.000000', NULL, 1),
(915565, 105072, 23394, '<td valign="top">great entry, fantastic job with the lighting.  hope this does well!</td>', 'great entry, fantastic job with the lighting.  hope this does well!', '2004-09-18 06:08:29.000000', NULL, 1),
(915568, 105145, 23394, '<td valign="top">this would probably score higher with 1) better smoke, and 2) a different title.  i''ve seen some people blow smoke through water (and i''m not admitting anything here), where the smoke looked actually intoxicating.  you might want to go back and work on this some more &lt;g&gt;</td>', 'this would probably score higher with 1) better smoke, and 2) a different title.  i''ve seen some people blow smoke through water (and i''m not admitting anything here), where the smoke looked actually intoxicating.  you might want to go back and work on this some more <g>', '2004-09-18 06:12:28.000000', NULL, 1),
(915569, 104940, 23394, '<td valign="top">i guess this fits the challenge, or else you wouldn''t have entered it...nice landscape.  great colors, nice lighting.</td>', 'i guess this fits the challenge, or else you wouldn''t have entered it...nice landscape.  great colors, nice lighting.', '2004-09-18 06:13:58.000000', NULL, 1),
(915570, 104876, 23394, '<td valign="top">smog? or lotsa clouds desaturated?  i''m really trying to keep from saying doesn''t meet the challenge, but it''s hard.  i mean, without the title, it would be an image of a sailboat on a cloudy day...</td>', 'smog? or lotsa clouds desaturated?  i''m really trying to keep from saying doesn''t meet the challenge, but it''s hard.  i mean, without the title, it would be an image of a sailboat on a cloudy day...', '2004-09-18 06:16:41.000000', NULL, 1),
(915571, 105073, 23394, '<td valign="top">nice shot.  love the colors, the birds, the lighting, the clouds.  other than the title, don''t really see how it fits the challenge, though.</td>', 'nice shot.  love the colors, the birds, the lighting, the clouds.  other than the title, don''t really see how it fits the challenge, though.', '2004-09-18 06:18:36.000000', NULL, 1),
(915572, 105036, 23394, '<td valign="top">i guess this is one of those shots that caused the great ''smoke vs steam'' debates...well, it doesn''t matter to me.  i would have liked this more with more of it, and with a different title.  wild colors, interesting lines.</td>', 'i guess this is one of those shots that caused the great ''smoke vs steam'' debates...well, it doesn''t matter to me.  i would have liked this more with more of it, and with a different title.  wild colors, interesting lines.', '2004-09-18 06:22:05.000000', NULL, 1),
(915577, 104564, 23394, '<td valign="top">i guess this is another one of those images that contributed to the great ''smoke vs steam'' debates.  i don''t care...this is a great shot.  i, for one, truly appreciate it, because i know how hard it is to be there at that time of day, and how easy it is to miss the shot when you get caught up in the beauty of being there.  great capture.  if you don''t mind, after the challenge, could you also put up the original in your portfolio?</td>', 'i guess this is another one of those images that contributed to the great ''smoke vs steam'' debates.  i don''t care...this is a great shot.  i, for one, truly appreciate it, because i know how hard it is to be there at that time of day, and how easy it is to miss the shot when you get caught up in the beauty of being there.  great capture.  if you don''t mind, after the challenge, could you also put up the original in your portfolio?', '2004-09-18 06:27:16.000000', NULL, 1),
(915579, 104611, 23394, '<td valign="top">and you just happened to be there with your camera!  at least, i hope you didn''t do this on purpose...</td>', 'and you just happened to be there with your camera!  at least, i hope you didn''t do this on purpose...', '2004-09-18 06:29:24.000000', NULL, 1),
(915581, 104655, 23394, '<td valign="top">wow...talk about opportunity meets challenge...way to be there.  great capture.  i''m partial to non-studio shots, where it''s just you and the camera, and the camera is the only thing you have control over.  hope this does well for you.</td>', 'wow...talk about opportunity meets challenge...way to be there.  great capture.  i''m partial to non-studio shots, where it''s just you and the camera, and the camera is the only thing you have control over.  hope this does well for you.', '2004-09-18 06:32:22.000000', NULL, 1),
(915585, 104490, 23394, '<td valign="top">interesting shot, nice bw.  wish you''d taken a moment to rotate for a level horizon.  don''t really understand the title.</td>', 'interesting shot, nice bw.  wish you''d taken a moment to rotate for a level horizon.  don''t really understand the title.', '2004-09-18 06:34:06.000000', NULL, 1),
(915588, 104801, 23394, '<td valign="top">ay-yi-yi...this is so close, it''s making my eyes water.</td>', 'ay-yi-yi...this is so close, it''s making my eyes water.', '2004-09-18 06:35:06.000000', NULL, 1),
(915640, 104752, 16912, '<td valign="top">I saw very little detail in this shot at first pass (I know, I have dark monitor problems) so I downloaded it and lightened somewhat in CS. Now I see what I hope was submitted? great capture of smoke, especially the lines. <br/> <br/>Bumped 2 points ;)</td>', 'I saw very little detail in this shot at first pass (I know, I have dark monitor problems) so I downloaded it and lightened somewhat in CS. Now I see what I hope was submitted? great capture of smoke, especially the lines.  Bumped 2 points ;)', '2004-09-18 08:17:53.000000', NULL, 1),
(915641, 104850, 16912, '<td valign="top">I like the colour in this shot but feel the smoke is a little thin - though you do get the feel of an overworked drive.</td>', 'I like the colour in this shot but feel the smoke is a little thin - though you do get the feel of an overworked drive.', '2004-09-18 08:19:38.000000', NULL, 1),
(915642, 104016, 16912, '<td valign="top">Nice shot and great positioning of the chimneys and smoke. not sure if you did any/much processing of the background but I like the effect anyway.  I did a quick desat of this and I think it would look good in b&amp;w.</td>', 'Nice shot and great positioning of the chimneys and smoke. not sure if you did any/much processing of the background but I like the effect anyway.  I did a quick desat of this and I think it would look good in b&w.', '2004-09-18 08:23:20.000000', NULL, 1),
(915647, 105004, 16912, '<td valign="top">Another shot missed on the first pass due to my dark monitor as I missed all that smoke floating upward. Wel presented challenge entry, the only thing I would say is when I downloaded it I tried a different crop and removed the hand, that is not a smokers way to hold a cigarette? the smoke then seemed to profile the face.<br/> <br/>Anyway, bumped an extra point after the second pass ;)</td>', 'Another shot missed on the first pass due to my dark monitor as I missed all that smoke floating upward. Wel presented challenge entry, the only thing I would say is when I downloaded it I tried a different crop and removed the hand, that is not a smokers way to hold a cigarette? the smoke then seemed to profile the face. Anyway, bumped an extra point after the second pass ;)', '2004-09-18 08:31:01.000000', NULL, 1),
(915649, 105063, 16912, '<td valign="top">Yup, I see smoke and lots of it, must have been some fire?  The building stands out well, nice clean shot.</td>', 'Yup, I see smoke and lots of it, must have been some fire?  The building stands out well, nice clean shot.', '2004-09-18 08:33:25.000000', NULL, 1),
(915651, 104974, 23394, '<td valign="top">without <a href="//www.trainweb.org/railwaytechnical/st-glos.html#F" rel="nofollow" target="_blank">googling the title</a>, i never would have known what this was.  now that i do, i can say, nice capture, good composition.  there is a lot of debate about titles, whether they are part of the image, separate from the image, or whether the image has no meaning without the title.  to me, it depends on how the image is going to be used--to illustrate an article in a train magazine, or in a challenge.  the only reason i''m going on about this is that i didn''t know what i was looking at until i took the time to find out what it was (it''s also 5:30 am and i can''t sleep).  i don''t know if most other voters take the time to look into something they don''t get within the first 2-3 seconds.  for what it''s worth...again, nice capture.</td>', 'without googling the title, i never would have known what this was.  now that i do, i can say, nice capture, good composition.  there is a lot of debate about titles, whether they are part of the image, separate from the image, or whether the image has no meaning without the title.  to me, it depends on how the image is going to be used--to illustrate an article in a train magazine, or in a challenge.  the only reason i''m going on about this is that i didn''t know what i was looking at until i took the time to find out what it was (it''s also 5:30 am and i can''t sleep).  i don''t know if most other voters take the time to look into something they don''t get within the first 2-3 seconds.  for what it''s worth...again, nice capture.', '2004-09-18 08:36:43.000000', NULL, 1),
(915652, 105036, 16912, '<td valign="top">I would personally have preferred the main focus to have been on the grid, I keep getting drawn to the passing vehicle and maybe a faster shutter would have shown more detail in the smoke/steam and the background seems a little busy for me (considering the challenge)</td>', 'I would personally have preferred the main focus to have been on the grid, I keep getting drawn to the passing vehicle and maybe a faster shutter would have shown more detail in the smoke/steam and the background seems a little busy for me (considering the challenge)', '2004-09-18 08:36:46.000000', NULL, 1),
(915653, 104355, 16912, '<td valign="top">Nice idea, but fror me would have preferred the smoke to be sharper, with more definition and the lighting on the hand makes it look strange (possibly your intention?) Good framing of the scene withing the image.</td>', 'Nice idea, but fror me would have preferred the smoke to be sharper, with more definition and the lighting on the hand makes it look strange (possibly your intention?) Good framing of the scene withing the image.', '2004-09-18 08:39:24.000000', NULL, 1),
(915655, 104324, 23394, '<td valign="top">let me go on and join the long list of commentors that have picked this to ribbon.  this is one of those shots that raises the bar for the rest of us.<br/> <br/>additional comments:  WOW!  HOW COOL!  AWESOME!  HOW DID YOU DO THIS?!?</td>', 'let me go on and join the long list of commentors that have picked this to ribbon.  this is one of those shots that raises the bar for the rest of us. additional comments:  WOW!  HOW COOL!  AWESOME!  HOW DID YOU DO THIS?!?', '2004-09-18 08:46:50.000000', NULL, 1),
(915684, 103661, 23956, '<td valign="top">Great idea, but the harsh lighting and the editing on the front of the sweater take away from the concept.</td>', 'Great idea, but the harsh lighting and the editing on the front of the sweater take away from the concept.', '2004-09-18 09:54:13.000000', NULL, 1),
(915686, 105133, 23956, '<td valign="top">Great idea! The flash is too strong (needs to be more evenly lit so it doesn''t look so staged), but otherwise, this is fabulous.</td>', 'Great idea! The flash is too strong (needs to be more evenly lit so it doesn''t look so staged), but otherwise, this is fabulous.', '2004-09-18 09:58:22.000000', NULL, 1),
(915688, 105051, 23956, '<td valign="top">I wish this weren''t so blurry, but it''s lovely.</td>', 'I wish this weren''t so blurry, but it''s lovely.', '2004-09-18 10:00:28.000000', NULL, 1),
(915690, 104973, 23956, '<td valign="top">This might have been better if you had reversed which candle was in front, so that the flame of the one that stayed lit wouldn''t be cut in half. I agree with having the snuffer extend past the first frame and more into the picture, the image would be too unbalanced if it only reached a little way into the image.</td>', 'This might have been better if you had reversed which candle was in front, so that the flame of the one that stayed lit wouldn''t be cut in half. I agree with having the snuffer extend past the first frame and more into the picture, the image would be too unbalanced if it only reached a little way into the image.', '2004-09-18 10:02:45.000000', NULL, 1),
(915693, 105036, 23956, '<td valign="top">This is a great shot. I love everything about it. There''s so much going on! The steam, the vehicles, the cross, the man in the red hat.... even the plant in the giant pot. There''s so much to look at, and I think you got the exposure and composition perfect. Very well done, and an interesting commentary!</td>', 'This is a great shot. I love everything about it. There''s so much going on! The steam, the vehicles, the cross, the man in the red hat.... even the plant in the giant pot. There''s so much to look at, and I think you got the exposure and composition perfect. Very well done, and an interesting commentary!', '2004-09-18 10:06:07.000000', NULL, 1),
(915702, 104842, 23956, '<td valign="top">In my mind I''m trying to turn these black blobs into silhouettes, but I think that this really points to a need for editing practice. To get a background darker, first use either brightness/contrast or levels to adjust it as much as you can. Then use your burn brush or a black colored paintbrush set to a low opacity (maybe 20%, depending on the situation) and low hardness, and layer in the darkness so that it blends more evenly. Right now I can see exactly where you darkened, and this smoke shouldn''t have any hard edges. By the way, a plain chunk of black velvet works beautifully as a black background, it reflects virtually no light. They actually used to use it before they used bluescreens, because when photographed it looks almost pure black. I finally bought a yard of it at the local fabric shop, and I do much less editing now!</td>', 'In my mind I''m trying to turn these black blobs into silhouettes, but I think that this really points to a need for editing practice. To get a background darker, first use either brightness/contrast or levels to adjust it as much as you can. Then use your burn brush or a black colored paintbrush set to a low opacity (maybe 20%, depending on the situation) and low hardness, and layer in the darkness so that it blends more evenly. Right now I can see exactly where you darkened, and this smoke shouldn''t have any hard edges. By the way, a plain chunk of black velvet works beautifully as a black background, it reflects virtually no light. They actually used to use it before they used bluescreens, because when photographed it looks almost pure black. I finally bought a yard of it at the local fabric shop, and I do much less editing now!', '2004-09-18 10:19:13.000000', NULL, 1),
(915703, 104846, 23956, '<td valign="top">Fun! We don''t see this part of fireworks photographed very often. I love the colored spotlights, where was this?</td>', 'Fun! We don''t see this part of fireworks photographed very often. I love the colored spotlights, where was this?', '2004-09-18 10:23:35.000000', NULL, 1),
(915704, 104695, 23956, '<td valign="top">Great shot! My only complaint is the shadow that your fill flash cast across his face.</td>', 'Great shot! My only complaint is the shadow that your fill flash cast across his face.', '2004-09-18 10:25:14.000000', NULL, 1),
(915728, 104647, 15575, '<td valign="top">I think this is really funny and a bit different to other entries I''ve seen so far.  I think you could make it more interesting my experimenting with lighting though.  7</td>', 'I think this is really funny and a bit different to other entries I''ve seen so far.  I think you could make it more interesting my experimenting with lighting though.  7', '2004-09-18 11:34:25.000000', NULL, 1),
(915731, 104503, 15575, '<td valign="top">A little bleached out on the bottle, otherwise I think this is a great pic</td>', 'A little bleached out on the bottle, otherwise I think this is a great pic', '2004-09-18 11:39:20.000000', NULL, 1),
(915882, 105022, 5585, '<td valign="top">Fantastic Capture...works for Me.....</td>', 'Fantastic Capture...works for Me.....', '2004-09-18 15:22:15.000000', NULL, 1),
(915886, 104734, 15832, '<td valign="top">This is cool. How you put all this together and than b&amp;w.<br/>Works perfect. Maby the smoke could be littel more spread because i think it would figo very well to the dark on his left side.<br/>But non the less... I like it alot. Wicked place you found for the puffer. Fits the atmorsphere perfeckt 8</td>', 'This is cool. How you put all this together and than b&w.Works perfect. Maby the smoke could be littel more spread because i think it would figo very well to the dark on his left side.But non the less... I like it alot. Wicked place you found for the puffer. Fits the atmorsphere perfeckt 8', '2004-09-18 15:28:28.000000', NULL, 1),
(915890, 104666, 15832, '<td valign="top">Wow... Spookey.<br/>I like it. 7</td>', 'Wow... Spookey.I like it. 7', '2004-09-18 15:33:04.000000', NULL, 1),
(915895, 104503, 5585, '<td valign="top">Great....Ya done Good !</td>', 'Great....Ya done Good !', '2004-09-18 15:40:25.000000', NULL, 1),
(915899, 104503, 15832, '<td valign="top">Now if only the background would be totally black this would be a ribbon maker...<br/>Maby your monitor is not calibrated (personally had alot of problems because of that)     The idea itself, is a 10 pointer but the pick of background is not working for me (personally)   btw. If you would have put the bottel under steam you could have removed the stikker without any glue remaning on the bottel (that is if you would have liked it) .  7<br/></td>', 'Now if only the background would be totally black this would be a ribbon maker...Maby your monitor is not calibrated (personally had alot of problems because of that)     The idea itself, is a 10 pointer but the pick of background is not working for me (personally)   btw. If you would have put the bottel under steam you could have removed the stikker without any glue remaning on the bottel (that is if you would have liked it) .  7', '2004-09-18 15:43:28.000000', NULL, 1),
