(917372, 104734, 12962, '<td valign="top">As I said, very distinctive ... distinctive JPR.  Top 20 is not bad ... goes straight to my favorites.<br/><br/><i>Message edited by author 2004-09-20 00:42:08.</i></td>', 'As I said, very distinctive ... distinctive JPR.  Top 20 is not bad ... goes straight to my favorites.', '2004-09-20 01:41:03.000000', '2004-09-20 01:42:08.000000', 0),
