(917379, 104647, 22734, '<td valign="top">This remains a humorous entry and one members are very unlikely to forget. Very well done.</td>', 'This remains a humorous entry and one members are very unlikely to forget. Very well done.', '2004-09-20 01:44:00.000000', NULL, 0),
(917382, 104734, 20779, '<td valign="top">Another awesome one.</td>', 'Another awesome one.', '2004-09-20 01:46:08.000000', NULL, 0),
(917392, 103484, 12962, '<td valign="top">Amazing planning and execution, congratulations!</td>', 'Amazing planning and execution, congratulations!', '2004-09-20 01:49:14.000000', NULL, 0),
(917393, 105063, 22734, '<td valign="top">Good choice here for b/w. A very nice natural composition. Yes, the smoke comes from the back of the building. The eye is faced with the massive black on the upper left and the pure white on the right.</td>', 'Good choice here for b/w. A very nice natural composition. Yes, the smoke comes from the back of the building. The eye is faced with the massive black on the upper left and the pure white on the right.', '2004-09-20 01:49:39.000000', NULL, 0),
(917395, 104324, 22734, '<td valign="top">Ericlimon: now I see your consternation. This is just beautiful and it fooled us all. Keep up the good work. There are more ideas where this came from. This is so unique I am placing it in my favs.<br/><br/><i>Message edited by author 2004-09-20 00:56:09.</i></td>', 'Ericlimon: now I see your consternation. This is just beautiful and it fooled us all. Keep up the good work. There are more ideas where this came from. This is so unique I am placing it in my favs.', '2004-09-20 01:52:20.000000', '2004-09-20 01:56:09.000000', 0),
(917427, 105072, 9668, '<td valign="top">Congrats on the red ribbon.</td>', 'Congrats on the red ribbon.', '2004-09-20 02:08:57.000000', NULL, 0),
(917437, 105014, 20375, '<td valign="top">Who had the audacity to copy Kiwinesses idea?<br/> <br/>I did.<br/>This is a tribute shot to an excellent photographer whom I admire and aspire to achieve his level of expertise.<br/>I loved "Fingering Ghost" and had always wanted to try a similar shot. Along came the Smoke Challenge which proved to be an excellent opportunity. Tried different things...lighting etc...and loved this one.<br/>What a wonderful learning experience and I am so pleased with the result.<br/> <br/>Thank you Gary, (Kiwiness) you should take pride in knowing you inspire others. Your inspiration took me to a new level....I broke the 7.00 score barrier!</td>', 'Who had the audacity to copy Kiwinesses idea? I did.This is a tribute shot to an excellent photographer whom I admire and aspire to achieve his level of expertise.I loved "Fingering Ghost" and had always wanted to try a similar shot. Along came the Smoke Challenge which proved to be an excellent opportunity. Tried different things...lighting etc...and loved this one.What a wonderful learning experience and I am so pleased with the result. Thank you Gary, (Kiwiness) you should take pride in knowing you inspire others. Your inspiration took me to a new level....I broke the 7.00 score barrier!', '2004-09-20 02:14:17.000000', NULL, 0),
(917467, 103484, 6130, '<td valign="top">Grattis!</td>', 'Grattis!', '2004-09-20 02:32:47.000000', NULL, 0),
(917474, 103484, 4090, '<td valign="top">Congratulations on the blue gary - another stunning photo.</td>', 'Congratulations on the blue gary - another stunning photo.', '2004-09-20 02:43:22.000000', NULL, 0),
(917489, 105072, 4090, '<td valign="top">Congrats on the red ribbon.wondered how you got the colours - tri-color filter .. cool</td>', 'Congrats on the red ribbon.wondered how you got the colours - tri-color filter .. cool', '2004-09-20 02:59:29.000000', NULL, 0),
(917491, 104908, 4090, '<td valign="top">great photo,Congratulations</td>', 'great photo,Congratulations', '2004-09-20 03:00:10.000000', NULL, 0),
